//! Frozen independent outputs generated by reference.py against the official
//! mlx-lm wheel. Prefill includes nonzero state; decode starts from that state.
use super::*;
use sha2::{Digest, Sha256};

fn values(shape: &[i32], salt: i32) -> Array {
    let count: i32 = shape.iter().product();
    let values: Vec<f32> = (0..count)
        .map(|i| f32::from(i16::try_from((i * 17 + salt) % 101 - 50).expect("small value")) / 256.0)
        .collect();
    Array::from_slice(&values, shape)
}

fn digest(array: &Array) -> String {
    let bytes = array.view_dtype(Dtype::Uint8).expect("bytes");
    bytes.eval().expect("evaluate");
    format!("{:x}", Sha256::digest(bytes.as_slice::<u8>()))
}

#[test]
fn recurrence_matches_pinned_prefill_and_decode_output_and_state() {
    let reference: serde_json::Value =
        serde_json::from_str(include_str!("reference.json")).expect("reference");
    assert_eq!(reference["packed_enabled"], "1");
    assert_eq!(
        reference["source_sha256"],
        "f69e837ea68641dbb06fdb5dcc024a9a7e1d9353f08ae58c05275253a0c39428"
    );
    for case in reference["cases"].as_array().expect("cases") {
        let dk = i32::try_from(case["dk"].as_i64().expect("dk")).expect("dk");
        let dv = i32::try_from(case["dv"].as_i64().expect("dv")).expect("dv");
        let mut state = values(&[2, dv, dk], 29)
            .transpose_axes(&[0, 2, 1])
            .expect("native state");
        for (step, (seq, salt)) in [(3, 0), (1, 37)].into_iter().enumerate() {
            let bf16 = |shape: &[i32], offset| {
                values(shape, salt + offset)
                    .as_dtype(Dtype::Bfloat16)
                    .expect("bf16")
            };
            let q = bf16(&[seq, 1, dk], 1);
            let k = bf16(&[seq, 1, dk], 3);
            let v = bf16(&[seq, 2, dv], 5);
            let g = values(&[seq, 2], salt + 7)
                .add(Array::from_f32(0.75))
                .expect("decay");
            let beta = values(&[seq, 2], salt + 11)
                .add(Array::from_f32(0.5))
                .expect("beta")
                .as_dtype(Dtype::Bfloat16)
                .expect("bf16");
            let previous = digest(&state.contiguous().expect("state bytes"));
            let query_before = digest(&q);
            let (output, next) = update(&q, &k, &v, &g, &beta, &state).expect("recurrence");
            assert_eq!(output.dtype(), Dtype::Bfloat16);
            assert_eq!(next.dtype(), Dtype::Float32);
            assert_eq!(next.shape(), &[2, dk, dv]);
            assert_eq!(
                digest(&output),
                case["steps"][step]["output"],
                "output dk={dk} dv={dv} step={step}"
            );
            assert_eq!(
                digest(
                    &next
                        .transpose_axes(&[0, 2, 1])
                        .expect("source layout")
                        .contiguous()
                        .expect("contiguous")
                ),
                case["steps"][step]["state"],
                "state dk={dk} dv={dv} step={step}"
            );
            assert_eq!(
                digest(&state.contiguous().expect("state bytes")),
                previous,
                "shared input state is immutable"
            );
            assert_eq!(digest(&q), query_before, "query is immutable");
            state = next;
        }
    }
}

#[test]
fn dispatch_preserves_generic_and_ops_shapes() {
    assert_eq!(path(128, 8), Path::Packed);
    assert_eq!(path(128, 7), Path::Scalar);
    assert_eq!(path(64, 8), Path::Scalar);
    assert_eq!(path(16, 8), Path::Ops);
    assert_eq!(path(33, 8), Path::Ops);
}

#[test]
fn invalid_inputs_fail_before_kernel_launch() {
    let q = values(&[1, 1, 16], 1);
    let v = values(&[1, 2, 7], 3);
    let gate = values(&[1, 2], 7);
    let state = values(&[2, 16, 7], 29);
    assert!(admit(&q, &q, &v, &gate, &gate, &state).is_ok());
    let empty = values(&[0, 1, 16], 1);
    assert!(matches!(
        update(&empty, &empty, &v, &gate, &gate, &state),
        Err(Qwen35Error::EmptyInput)
    ));
    assert!(
        admit(
            &q,
            &q,
            &v,
            &gate,
            &gate,
            &state.transpose_axes(&[0, 2, 1]).expect("wrong state")
        )
        .is_err()
    );
    assert!(
        admit(
            &q,
            &q,
            &v,
            &gate.as_dtype(Dtype::Bfloat16).expect("wrong gate"),
            &gate,
            &state
        )
        .is_err()
    );
    let bad_heads = values(&[1, 3, 16], 1);
    assert!(admit(&bad_heads, &bad_heads, &v, &gate, &gate, &state).is_err());
}
